using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using PKHeX.Core;

namespace PKHeX.Gen9LegalityProbe;

/// <summary>
/// Generates FIXTURE-ONLY PK9 files from the actual original 4.0.0 pkNX
/// native encounter resource. They are NOT real game-captured PK9 files.
/// The exact SAME generated bytes must be passed to the two separate
/// reference/embedded-native PKHeX.Core LegalityAnalysis builds.
/// </summary>
internal static class DeltaFixtureMaker
{
    private const string WildName = "encounter_wild_paldea.pkl";
    private const string FixedName = "encounter_fixed_paldea.pkl";

    internal static object Prepare(string native, string diff, string dest)
    {
        if (!Directory.Exists(native) || !Directory.Exists(diff))
            throw new DirectoryNotFoundException("Original source-generated .pkl and real difference CSV must both exist");
        Directory.CreateDirectory(dest);
        if (Directory.EnumerateFiles(dest,"*.pk9").Any())
            throw new InvalidDataException("Do not silently reuse old PK9 delta test files");

        var wildRaw=VerifiedData(native,WildName);
        var fixedRaw=VerifiedData(native,FixedName);
        var fixedNative=Csv(Path.Combine(diff,"fixed_native_only.csv"));
        var wildNative=Csv(Path.Combine(diff,"wild_native_only.csv"));
        var wildMissing=Csv(Path.Combine(diff,"wild_pkhex_only.csv"));
        if(fixedNative.Count<100 || wildNative.Count<3000 || wildMissing.Count<600)
            throw new InvalidDataException("This is not the original full 4.0.0 203/3655 native difference dataset");

        var trainer=new SimpleTrainerInfo(GameVersion.SL)
        {
            OT="DeltaAudit",Gender=0,Language=(int)LanguageID.English,
            TID16=2026,SID16=1107,
        };
        var entries=new List<object>();
        int fixedCount=0, crossoverCount=0, levelCount=0, failedConversions=0;
        var fixedSlots=EncounterFixed9.GetArray(fixedRaw);
        var fixedUsed=new HashSet<string>(StringComparer.Ordinal);
        for(int i=0;i<fixedSlots.Length && fixedCount<32;i++)
        {
            var slot=fixedSlots[i];
            var bytes=fixedRaw.AsSpan(i*20,20);
            if (!new[]{bytes[0x10],bytes[0x11],bytes[0x12],bytes[0x13]}.Contains((byte)158))
                continue;
            if (!fixedNative.Any(r=>FixedMatch(bytes,r)))
                continue; // Source is actual previously classified nonmatching native record.
            if(!fixedUsed.Add($"{slot.Species}/{slot.Form}/{slot.Level}"))
                continue;
            try
            {
                var pk=slot.ConvertToPKM(trainer);
                pk.MetLocation=158; // Explicitly exercise the 191 added Mossfell Confluence location alternatives.
                pk.RefreshChecksum();
                Save(dest,$"fixed_158_{slot.Species:D4}_{slot.Level:D3}_{i:D3}.pk9",pk,entries,"fixed_added_location_158",FixedName);
                fixedCount++;
            }
            catch(Exception ex) when(ex is ArgumentException or IndexOutOfRangeException or InvalidOperationException)
            {
                Console.Error.WriteLine($"Fixed native delta candidate {slot.Species} blocked: {ex.Message}");
                failedConversions++;
            }
        }
        if(fixedCount==0)
            throw new InvalidDataException("No real fixed native-only alternative location 158 templates can generate PK9");

        var nativeKeys=wildNative.Select(Key).ToHashSet(StringComparer.Ordinal);
        var refBySig=wildMissing.GroupBy(Sig).ToDictionary(
            x=>x.Key,x=>x.Max(y=>y["level_max"]),StringComparer.Ordinal);
        var areas=EncounterArea9.GetAreas(BinLinkerAccessor.Get(wildRaw),GameVersion.SV);
        var crossUsed=new HashSet<string>(StringComparer.Ordinal);
        var levelUsed=new HashSet<string>(StringComparer.Ordinal);
        foreach(var area in areas)
        {
            if(area.Location<132 || area.Location>=174) continue; // Primary real discrepancy: Kitakami.
            foreach(var slot in area.Slots)
            {
                var key=Key(area,slot);
                if(!nativeKeys.Contains(key) || slot.Species==0 || slot.LevelMin==0)continue;
                if(area.CrossFrom!=0 && crossoverCount<32 &&
                    crossUsed.Add($"{area.Location}/{area.CrossFrom}/{slot.Species}"))
                {
                    try
                    {
                        var pk=slot.ConvertToPKM(trainer);
                        // The capture area (where the player is) differs from the
                        // source spawn area's CrossFrom for bleed/crossover cases.
                        pk.MetLocation=area.Location;
                        pk.RefreshChecksum();
                        Save(dest,$"cross_{area.Location:D3}_{area.CrossFrom:D3}_{slot.Species:D4}_{crossoverCount:D2}.pk9",
                             pk,entries,"wild_kitakami_native_only_crossover",WildName);
                        crossoverCount++;
                    }
                    catch(Exception ex) when(ex is ArgumentException or IndexOutOfRangeException or InvalidOperationException)
                    {
                        Console.Error.WriteLine($"Wild crossover {slot.Species} blocked: {ex.Message}");
                        failedConversions++;
                    }
                }
                var sig=Sig(area,slot);
                if (levelCount<24 && refBySig.TryGetValue(sig,out var refMax) &&
                    slot.LevelMax>refMax && slot.LevelMax<=100 &&
                    levelUsed.Add($"{area.Location}/{slot.Species}/{slot.LevelMax}"))
                {
                    try
                    {
                        var pk=slot.ConvertToPKM(trainer);
                        pk.MetLocation=area.Location;
                        pk.MetLevel=slot.LevelMax; // Focus on level allowed natively above pinned reference.
                        pk.CurrentLevel=slot.LevelMax;
                        pk.ObedienceLevel=slot.LevelMax;
                        pk.RefreshChecksum();
                        Save(dest,$"level_{area.Location:D3}_{slot.Species:D4}_{slot.LevelMax:D3}_{levelCount:D2}.pk9",
                             pk,entries,"wild_native_new_max_level",WildName);
                        levelCount++;
                    }
                    catch(Exception ex) when(ex is ArgumentException or IndexOutOfRangeException or InvalidOperationException)
                    {
                        Console.Error.WriteLine($"Native level-delta {slot.Species} blocked: {ex.Message}");
                        failedConversions++;
                    }
                }
            }
        }
        if(crossoverCount==0 || levelCount==0)
            throw new InvalidDataException($"No independent real wild crossover/level delta PK9: crossover={crossoverCount}, level={levelCount}");

        var result=new
        {
            status="NATIVE_PKNX_DIFF_SOURCE_PK9_FIXTURES_NOT_GAME_CAPTURED",
            sourceVersion="SV 4.0.0",
            fixedAdded158=fixedCount,
            kitakamiCrossovers=crossoverCount,
            levelDeltaCandidates=levelCount,
            unsuccessfulCandidateConversions=failedConversions,
            totalCases=entries.Count,
            cases=entries,
            warning="Generated PK9 are controlled fixtures; they do not prove real in-game encounter odds or PID/RNG.",
        };
        File.WriteAllText(Path.Combine(dest,"delta-source-proof.json"),
                          JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true})+"\n",Encoding.UTF8);
        Console.WriteLine(JsonSerializer.Serialize(new {result.status,result.fixedAdded158,result.kitakamiCrossovers,result.levelDeltaCandidates}));
        return result;
    }

    private static byte[] VerifiedData(string root,string name)
    {
        var manifest=Path.Combine(root,"native-encounter-build.json");
        using var doc=JsonDocument.Parse(File.ReadAllBytes(manifest));
        var build=doc.RootElement;
        if(build.GetProperty("status").GetString()!="GENERATED_FROM_4_0_0_NATIVE_M2_VERIFIED_SOURCES" ||
           build.GetProperty("collisionBlocker").ValueKind!=JsonValueKind.Null ||
           build.GetProperty("originalTrcolEntries").GetInt32()!=223)
            throw new InvalidDataException("Native 4.0.0 and all 223 Havok collisions must be SHA-verified");
        foreach(var entry in build.GetProperty("generated").EnumerateArray())
        {
            if(entry.GetProperty("name").GetString()!=name)continue;
            var raw=File.ReadAllBytes(Path.Combine(root,name));
            var sha=Convert.ToHexString(SHA256.HashData(raw));
            if(entry.GetProperty("bytes").GetInt64()!=raw.LongLength ||
               entry.GetProperty("sha256").GetString()!=sha)
                throw new InvalidDataException($"Native {name} bytes or SHA256 not matching original build");
            return raw;
        }
        throw new FileNotFoundException($"No genuine original native PKHeX template evidence for {name}");
    }

    private static List<Dictionary<string,int>> Csv(string path)
    {
        using var sr=new StreamReader(path,Encoding.UTF8,true);
        var first=sr.ReadLine()??throw new InvalidDataException($"Empty original diff file {path}");
        var headers=first.Trim('\uFEFF').Split(',');
        var result=new List<Dictionary<string,int>>();
        for(string? line=sr.ReadLine();line!=null;line=sr.ReadLine())
        {
            if(line.Length==0)continue;
            var values=line.Split(',');
            if(values.Length!=headers.Length)
                throw new InvalidDataException($"Invalid real Gen9 diff CSV width {path}");
            var row=new Dictionary<string,int>(StringComparer.Ordinal);
            for(int i=0;i<headers.Length;i++)
                row.Add(headers[i],int.Parse(values[i],System.Globalization.CultureInfo.InvariantCulture));
            result.Add(row);
        }
        return result;
    }

    private static bool FixedMatch(ReadOnlySpan<byte> bytes,Dictionary<string,int> r)
    {
        if(BinaryPrimitives.ReadUInt16LittleEndian(bytes)!=r["species_national"] ||
           bytes[2]!=r["form_raw"] || bytes[3]!=r["level"] ||
           bytes[4]!=r["flawless_iv_count"] || bytes[5]!=r["tera_type_raw"] ||
           bytes[6]!=r["gender_raw"] || bytes[7]!=r["ability_permission_raw"])
            return false;
        for(int i=0;i<4;i++)
            if(BinaryPrimitives.ReadUInt16LittleEndian(bytes.Slice(8+i*2))!=r[$"move{i+1}"] ||
               bytes[16+i]!=r[$"location{i}"])
                return false;
        return true;
    }

    private static string Key(Dictionary<string,int> row) => string.Join("/",new[]
    {
        row["location_id"],row["cross_from_id"],row["species_national"],
        row["form_raw"],row["gender_raw"],row["level_min"],row["level_max"],
        row["time_forbidden_mask"],row["weather_allowed_mask"],
    });
    private static string Sig(Dictionary<string,int> row) => string.Join("/",new[]
    {
        row["location_id"],row["cross_from_id"],row["species_national"],
        row["form_raw"],row["gender_raw"],row["time_forbidden_mask"],row["weather_allowed_mask"],
    });
    private static string Key(EncounterArea9 area,EncounterSlot9 slot) => string.Join("/",new object[]
    {
        area.Location,area.CrossFrom,slot.Species,slot.Form,slot.Gender,
        slot.LevelMin,slot.LevelMax,slot.Time,(byte)slot.Weather,
    });
    private static string Sig(EncounterArea9 area,EncounterSlot9 slot) => string.Join("/",new object[]
    {
        area.Location,area.CrossFrom,slot.Species,slot.Form,slot.Gender,slot.Time,(byte)slot.Weather,
    });

    private static void Save(string path,string name,PK9 pk,List<object> rows,string category,string table)
    {
        if(pk.Data.Length!=344)
            throw new InvalidDataException("Only actual PK9 344-byte party data supported");
        var data=pk.Data.ToArray();
        var sha=Convert.ToHexString(SHA256.HashData(data));
        File.WriteAllBytes(Path.Combine(path,name),data);
        rows.Add(new
        {
            name,category,table,sha256=sha,
            species=pk.Species,form=pk.Form,metLocation=pk.MetLocation,
            metLevel=pk.MetLevel,pk9Source="generated from actual game-native encounter template (not captured)",
        });
    }
}
